using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class AuditLogsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("AuditLogs", "View"); return AdminDataService.GetList("AuditLogs"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("AuditLogs", "View"); return AdminDataService.GetDefinitionMetadata("AuditLogs"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("AuditLogs", "Delete"); return AdminDataService.Delete("AuditLogs", id); } } }
